const envelope = $json ?? {};
const raw = envelope.query && typeof envelope.query === 'object' ? { ...envelope.query, sourceText: envelope.sourceText, sessionId: envelope.sessionId } : envelope;
const sourceText = typeof raw.sourceText === 'string' ? raw.sourceText.normalize('NFKC') : '';
const labeledFields = sourceText.match(/(?:שם|Name)\s*:\s*(.+?)\s*;\s*(?:אימייל|Email)\s*:\s*([^\s;]+)\s*;\s*(?:הודעה|Message)\s*:\s*([\s\S]+?)\s*$/i);
const name = labeledFields?.[1]?.trim() || (typeof raw.name === 'string' ? raw.name.trim() : '');
const email = (labeledFields?.[2]?.trim() || (typeof raw.email === 'string' ? raw.email.trim() : '')).toLowerCase();
const message = labeledFields?.[3]?.trim() || (typeof raw.message === 'string' ? raw.message.trim() : '');
const sourceTextLower = sourceText.toLowerCase();
const rawLanguage = typeof raw.language === 'string' ? raw.language.trim() : '';
const language = rawLanguage === 'he' ? 'he' : rawLanguage === 'en' ? 'en' : '';
const sessionId = typeof raw.sessionId === 'string' ? raw.sessionId.trim() : '';
const consent = raw.consent === true;
const emailIsValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && email.length <= 254;
const nameIsValid = Boolean(name) && name.length <= 120;
const messageIsValid = Boolean(message) && message.length <= 4000;
const validationErrors = [];
if (!consent) validationErrors.push('consent');
if (!nameIsValid) validationErrors.push('name');
if (!emailIsValid) validationErrors.push('email');
if (!messageIsValid) validationErrors.push('message');
if (nameIsValid && !sourceText.includes(name)) validationErrors.push('name_source');
if (emailIsValid && !sourceTextLower.includes(email)) validationErrors.push('email_source');
if (messageIsValid && !sourceText.includes(message)) validationErrors.push('message_source');
if (!language) validationErrors.push('language');
if (!sessionId || sessionId.length > 256) validationErrors.push('sessionId');
const valid = validationErrors.length === 0;
const requestMaterial = `${sessionId}\n${email}\n${message}`;
return [{ json: { name, email, message, language, consent, sessionId, valid, validationErrors, requestMaterial } }];

const errors = Array.isArray($json.validationErrors) ? $json.validationErrors : [];
const hasSourceError = errors.some((error) => error.endsWith('_source'));
const language = $json.language === 'he' ? 'he' : 'en';
const collectionPrompt = language === 'he' ? 'נא לשלוח בהודעה אחת את השם, כתובת האימייל וההודעה שברצונך להעביר לדניאל.' : 'Please send your name, email address, and message together in one new message.';
const genericPrompt = language === 'he' ? 'לא ניתן לשמור את הפנייה. יש לוודא שניתנה הסכמה ושכל הפרטים תקינים.' : 'The inquiry could not be saved. Please confirm consent and check all details.';
return [{ json: { requestId: 'invalid-request', status: 'invalid', stored: false, notificationAttempted: false, safeMessage: hasSourceError ? collectionPrompt : genericPrompt } }];

const outcome = ['success', 'failure', 'unknown'].includes($json.simulationOutcome) ? $json.simulationOutcome : 'unknown';
const statusByOutcome = { success: 'simulated_success', failure: 'simulated_failure', unknown: 'simulated_unknown' };
const safeMessageByLanguage = {
  he: { success: 'הסימולציה הצליחה. לא נשמרה פנייה ולא נשלח אימייל.', failure: 'הסימולציה החזירה כשל. לא נשמרה פנייה ולא נשלח אימייל.', unknown: 'תוצאת הסימולציה אינה ידועה. לא נשמרה פנייה ולא נשלח אימייל.' },
  en: { success: 'The simulation succeeded. No inquiry was saved and no email was sent.', failure: 'The simulation returned a failure. No inquiry was saved and no email was sent.', unknown: 'The simulation result is unknown. No inquiry was saved and no email was sent.' }
};
const language = $json.language === 'he' ? 'he' : 'en';
return [{ json: { requestId: $json.requestId, status: statusByOutcome[outcome], stored: false, notificationAttempted: false, simulated: true, safeMessage: safeMessageByLanguage[language][outcome] } }];

const lead = $('Generate Request ID').first().json;
const duplicateFound = typeof $json.requestId === 'string' && $json.requestId === lead.requestId;
return [{ json: { ...lead, duplicateFound } }];

const lead = typeof $ === 'function' ? $('Generate Request ID').first().json : $json;
const safeMessage = lead.language === 'he' ? 'הפנייה הזו כבר נשמרה.' : 'This inquiry has already been saved.';
return [{ json: { requestId: lead.requestId, status: 'duplicate', stored: true, notificationAttempted: false, safeMessage } }];

const lead = $('Generate Request ID').first().json;
const rowNumber = Number($json.row_number);
const appendConfirmed = typeof $json.requestId === 'string' && $json.requestId === lead.requestId && Number.isInteger(rowNumber) && rowNumber > 1;
return [{ json: { ...lead, row_number: rowNumber, appendConfirmed } }];

const lead = typeof $ === 'function' ? $('Generate Request ID').first().json : $json;
const requestId = typeof lead.requestId === 'string' ? lead.requestId : 'storage-failed';
const safeMessage = lead.language === 'he' ? 'לא ניתן לשמור את הפנייה כרגע. אפשר לנסות שוב מאוחר יותר.' : 'The inquiry could not be saved right now. Please try again later.';
return [{ json: { requestId, status: 'storage_failed', stored: false, notificationAttempted: false, safeMessage } }];

const lead = $('Storage Confirmed').first().json;
const errorText = JSON.stringify($json ?? {}).toLowerCase();
const uncertainTransportFailure = ['timeout', 'timed out', 'etimedout', 'econnreset', 'socket hang up', 'network'].some((marker) => errorText.includes(marker));
return [{ json: { ...lead, emailStatus: uncertainTransportFailure ? 'unknown' : 'failed' } }];

let outcome = $json ?? {};
if (!outcome.requestId || !['sent', 'failed', 'unknown'].includes(outcome.emailStatus)) {
  for (const nodeName of ['Gmail Sent Outcome', 'Gmail Unknown Outcome', 'Gmail Failed Outcome']) {
    const nodeOutput = $(nodeName);
    if (nodeOutput.isExecuted) {
      const candidate = nodeOutput.first().json;
      if (candidate?.requestId && ['sent', 'failed', 'unknown'].includes(candidate.emailStatus)) {
        outcome = candidate;
        break;
      }
    }
  }
}
const emailStatus = ['sent', 'failed', 'unknown'].includes(outcome.emailStatus) ? outcome.emailStatus : 'unknown';
const statusByEmail = { sent: 'stored_and_notified', failed: 'stored_notification_failed', unknown: 'stored_notification_unknown' };
const language = outcome.language === 'he' ? 'he' : 'en';
const messages = {
  he: { sent: 'הפנייה נשמרה ונשלחה לדניאל.', failed: 'הפנייה נשמרה, אך הודעת המייל לא נשלחה.', unknown: 'הפנייה נשמרה, אך מצב שליחת המייל אינו ידוע.' },
  en: { sent: 'Your inquiry was saved and sent to Daniel.', failed: 'Your inquiry was saved, but the email notification failed.', unknown: 'Your inquiry was saved, but the email notification status is unknown.' }
};
return [{ json: { requestId: outcome.requestId, status: statusByEmail[emailStatus], stored: true, notificationAttempted: true, safeMessage: messages[language][emailStatus] } }];

const lead = $('Storage Confirmed').first().json;
const safeMessage = lead.language === 'he' ? 'הפנייה נשמרה, אך מצב שליחת המייל אינו ידוע.' : 'Your inquiry was saved, but the email notification status is unknown.';
return [{ json: { requestId: lead.requestId, status: 'stored_notification_unknown', stored: true, notificationAttempted: true, safeMessage } }];
